// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.faceimport com.roshan.persona.vision.core.ConfidenceTierimport com.roshan.persona.vision.core.ConfidenceTieredResultimport com.roshan.persona.vision.ocr.BoundingBox/** * NOUS — Face Detection Data Models (Module 6 v4 — Step 6.4). * * Data structures for face DETECTION (not recognition — hard privacy line). * * ## Privacy (per strategy v4 §"Privacy & Security") * *  - **NOUS has ZERO face recognition capability by default.** *  - NOUS can DETECT faces (bounding boxes + landmarks + contours) but CANNOT *    identify who they are. *  - There is NO face-recognition model in the APK. This is a hard architectural line. *  - [FacePrivacyGuard] enforces this — it hard-blocks any "who is this" intent *    and prevents any face-embedding generation. *  - Face-tagging (opt-in × 3 + AES-256 + biometric-derived key) is deferred to v5 *    after privacy review. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Privacy: No Face Recognition</a> */// ═══════════════════════════════════════════════════════════════════════════// 1. DETECTED FACE// ═══════════════════════════════════════════════════════════════════════════/** * One face detected in an image. * * @param boundingBox normalized face bounding box (0.0-1.0). * @param confidence detection confidence (0.0-1.0). * @param landmarks facial landmarks (eyes, nose, mouth, ears) — null if not detected. * @param contours face contours (face oval, eyes, lips) — null if not detected. * @param smileProbability probability the person is smiling (0.0-1.0) — null if not available. * @param leftEyeOpenProbability probability left eye is open (0.0-1.0) — null if not available. * @param rightEyeOpenProbability probability right eye is open (0.0-1.0) — null if not available. * @param headEulerAngleX head rotation around X axis (degrees) — null if not available. * @param headEulerAngleY head rotation around Y axis (degrees) — null if not available. * @param headEulerAngleZ head rotation around Z axis (degrees) — null if not available. */data class DetectedFace(    val boundingBox: BoundingBox,    val confidence: Float,    val landmarks: FaceLandmarks? = null,    val contours: FaceContours? = null,    val smileProbability: Float? = null,    val leftEyeOpenProbability: Float? = null,    val rightEyeOpenProbability: Float? = null,    val headEulerAngleX: Float? = null,    val headEulerAngleY: Float? = null,    val headEulerAngleZ: Float? = null,) {    /** True if the face is smiling (probability ≥ 0.75). */    val isSmiling: Boolean?        get() = smileProbability?.let { it >= 0.75f }    /** True if both eyes are open (probability ≥ 0.5 for both). */    val areEyesOpen: Boolean?        get() = leftEyeOpenProbability?.let { left ->            rightEyeOpenProbability?.let { right ->                left >= 0.5f && right >= 0.5f            }        }    /** True if the face is roughly frontal (|eulerX| < 15° and |eulerY| < 15°). */    val isFrontal: Boolean        get() = (headEulerAngleX == null || kotlin.math.abs(headEulerAngleX) < 15f) &&                (headEulerAngleY == null || kotlin.math.abs(headEulerAngleY) < 15f)    /** Estimated face size category (for auto-crop decisions). */    val sizeCategory: FaceSizeCategory        get() = when {            boundingBox.area > 0.25f -> FaceSizeCategory.LARGE            boundingBox.area > 0.05f -> FaceSizeCategory.MEDIUM            else -> FaceSizeCategory.SMALL        }}/** Face size category (for auto-crop + UI decisions). */enum class FaceSizeCategory(val displayName: String) {    /** Face area > 25% of image — close-up portrait. */    LARGE("Large (Close-up)"),    /** Face area 5-25% of image — standard portrait. */    MEDIUM("Medium (Portrait)"),    /** Face area < 5% of image — distant/group photo. */    SMALL("Small (Distant)"),}// ═══════════════════════════════════════════════════════════════════════════// 2. FACE LANDMARKS// ═══════════════════════════════════════════════════════════════════════════/** * Facial landmarks detected by ML Kit. * * Each landmark is a normalized (x, y) coordinate (0.0-1.0) within the image. */data class FaceLandmarks(    val leftEye: LandmarkPoint?,    val rightEye: LandmarkPoint?,    val leftEar: LandmarkPoint?,    val rightEar: LandmarkPoint?,    val noseBase: LandmarkPoint?,    val mouthLeft: LandmarkPoint?,    val mouthRight: LandmarkPoint?,    val mouthBottom: LandmarkPoint?,    val leftCheek: LandmarkPoint?,    val rightCheek: LandmarkPoint?,) {    /** Compute the eye-to-eye distance (normalized). */    val eyeDistance: Float?        get() = leftEye?.let { l -> rightEye?.let { r ->            kotlin.math.sqrt((r.x - l.x).square() + (r.y - l.y).square())        } }    /** Compute the face center (midpoint between eyes). */    val faceCenter: LandmarkPoint?        get() = leftEye?.let { l -> rightEye?.let { r ->            LandmarkPoint((l.x + r.x) / 2f, (l.y + r.y) / 2f)        } }}/** A normalized (0.0-1.0) landmark point. */data class LandmarkPoint(val x: Float, val y: Float) {    init {        require(x in 0f..1f) { "x must be 0-1: $x" }        require(y in 0f..1f) { "y must be 0-1: $y" }    }}private fun Float.square(): Float = this * this// ═══════════════════════════════════════════════════════════════════════════// 3. FACE CONTOURS// ═══════════════════════════════════════════════════════════════════════════/** * Face contours (for advanced face shape analysis + auto-crop alignment). */data class FaceContours(    val faceOval: List<LandmarkPoint>,    val leftEyeContour: List<LandmarkPoint>,    val rightEyeContour: List<LandmarkPoint>,    val leftEyebrowTop: List<LandmarkPoint>,    val leftEyebrowBottom: List<LandmarkPoint>,    val rightEyebrowTop: List<LandmarkPoint>,    val rightEyebrowBottom: List<LandmarkPoint>,    val noseBridge: List<LandmarkPoint>,    val noseBottom: List<LandmarkPoint>,    val upperLipTop: List<LandmarkPoint>,    val upperLipBottom: List<LandmarkPoint>,    val lowerLipTop: List<LandmarkPoint>,    val lowerLipBottom: List<LandmarkPoint>,)// ═══════════════════════════════════════════════════════════════════════════// 4. FACE DETECTION RESULT// ═══════════════════════════════════════════════════════════════════════════/** * Result of face detection on an image. * * @param faces list of detected faces. * @param imageWidth original image width (pixels). * @param imageHeight original image height (pixels). * @param processingTimeMs detection time. */data class FaceDetectionResult(    val faces: List<DetectedFace>,    val imageWidth: Int,    val imageHeight: Int,    val processingTimeMs: Long,) {    /** Number of faces detected. */    val faceCount: Int get() = faces.size    /** True if any faces detected. */    val hasFaces: Boolean get() = faces.isNotEmpty()    /** True if multiple faces detected (group photo). */    val isGroupPhoto: Boolean get() = faces.size > 1    /** Get the largest face (by bounding box area). */    val largestFace: DetectedFace?        get() = faces.maxByOrNull { it.boundingBox.area }    /** Get all smiling faces. */    val smilingFaces: List<DetectedFace>        get() = faces.filter { it.isSmiling == true }}/** Tiered face detection result. */typealias TieredFaceResult = ConfidenceTieredResult<FaceDetectionResult>/** Build a tiered result from face detection (confidence = max face confidence). */fun tieredFaceResult(result: FaceDetectionResult): TieredFaceResult {    val maxConfidence = result.faces.maxOfOrNull { it.confidence } ?: 0f    return ConfidenceTieredResult.from(result, maxConfidence)}// ═══════════════════════════════════════════════════════════════════════════// 5. FACE PRIVACY GUARD (Hard Architectural Line)// ═══════════════════════════════════════════════════════════════════════════/** * NOUS — Face Privacy Guard (Module 6 v4 — Step 6.4, CRITICAL). * * Enforces the hard architectural privacy line: **NOUS detects faces but * NEVER identifies them.** * * ## What this guard does * *  1. **Blocks "who is this" intents** — If the Brain sends an intent asking *     to identify a person from their face, this guard rejects it immediately. *  2. **Blocks face-embedding generation** — No code path can generate a face *     embedding (the precursor to face recognition). *  3. **Logs privacy violations** — Any attempt to call recognition methods *     is logged for security audit. *  4. **Documentation enforcement** — The guard's existence is itself a *     privacy guarantee (code reviewers can see the hard line). * * ## Why this matters (per strategy v4 §"Issue 5: Privacy Contradiction") * * v3 had a contradiction: "No face recognition" (hard line) but "Optional * face-tagging" with face embeddings. v4 clarifies: * * > "NOUS has ZERO face recognition capability by default. NOUS can detect * > faces (bounding boxes + landmarks) but cannot identify who they are. * > If the user explicitly enables face-tagging (3 confirmations), NOUS * > generates a face embedding for each tagged person — but this embedding is * > AES-256 encrypted with a biometric-derived key and never leaves the device." * * Face-tagging is **deferred to v5** (after privacy review). For v4, this * guard hard-blocks ALL embedding generation. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Issue 5: Privacy Contradiction</a> */object FacePrivacyGuard {    /** True if face-tagging is enabled (always false in v4 — v5 will make this configurable). */    @Volatile    private var faceTaggingEnabled: Boolean = false    /**     * Check if a face operation is allowed.     *     * @param operation the operation to check.     * @return true if allowed, false if blocked by privacy guard.     */    fun isAllowed(operation: FaceOperation): Boolean {        return when (operation) {            FaceOperation.DETECT -> true  // Detection always allowed.            FaceOperation.CROP -> true    // Cropping always allowed.            FaceOperation.LANDMARK_EXTRACTION -> true  // Landmarks always allowed.            FaceOperation.CONTOUR_EXTRACTION -> true   // Contours always allowed.            FaceOperation.SMILE_DETECTION -> true      // Smile probability always allowed.            FaceOperation.EYE_OPEN_DETECTION -> true   // Eye open probability always allowed.            FaceOperation.EMBEDDING_GENERATION -> faceTaggingEnabled  // Blocked by default.            FaceOperation.RECOGNITION -> false  // ALWAYS blocked — hard line.            FaceOperation.IDENTIFICATION -> false  // ALWAYS blocked — hard line.            FaceOperation.COMPARISON -> false  // ALWAYS blocked — hard line.        }    }    /**     * Assert that an operation is allowed — throws [FacePrivacyViolationException]     * if blocked.     */    fun assertAllowed(operation: FaceOperation) {        if (!isAllowed(operation)) {            throw FacePrivacyViolationException(operation)        }    }    /**     * Enable face-tagging (v5 only — not callable in v4).     *     * In v4, this method is a no-op that always returns false.     * v5 will implement the triple opt-in + biometric key derivation.     */    fun enableFaceTagging(): Boolean {        // v4: Always returns false — face-tagging not available.        // v5: Will require triple opt-in + BiometricPrompt + AES-256 key derivation.        return false    }    /** Disable face-tagging (if enabled in v5). */    fun disableFaceTagging() {        faceTaggingEnabled = false    }    /** True if face-tagging is currently enabled. */    fun isFaceTaggingEnabled(): Boolean = faceTaggingEnabled}/** Face operations that the privacy guard can check. */enum class FaceOperation(val displayName: String) {    /** Detect face bounding boxes. Always allowed. */    DETECT("Detect Faces"),    /** Crop image to face bounding box. Always allowed. */    CROP("Crop to Face"),    /** Extract facial landmarks (eyes, nose, mouth). Always allowed. */    LANDMARK_EXTRACTION("Extract Landmarks"),    /** Extract face contours (oval, eyes, lips). Always allowed. */    CONTOUR_EXTRACTION("Extract Contours"),    /** Detect smile probability. Always allowed. */    SMILE_DETECTION("Detect Smile"),    /** Detect eye-open probability. Always allowed. */    EYE_OPEN_DETECTION("Detect Eye Open State"),    /** Generate face embedding (precursor to recognition). Blocked by default. */    EMBEDDING_GENERATION("Generate Face Embedding"),    /** Recognize/identify a person. ALWAYS blocked — hard privacy line. */    RECOGNITION("Recognize Person"),    /** Identify who a face belongs to. ALWAYS blocked — hard privacy line. */    IDENTIFICATION("Identify Person"),    /** Compare two faces for similarity. ALWAYS blocked — hard privacy line. */    COMPARISON("Compare Faces"),}/** * Thrown when a face operation is blocked by [FacePrivacyGuard]. * * This is a security-relevant exception — should be logged + audited. */class FacePrivacyViolationException(    val operation: FaceOperation,) : RuntimeException(    "Face operation blocked by privacy guard: $operation. " +    "NOUS does not perform face recognition or identification. " +    "Face-tagging (opt-in, encrypted) is available in v5.")